# The Fusion implementation of the decad, sketch and r3 operations that translated gallery models call.
#
# A gear add-in generated by port/cmd/gearport holds Python translated from a decad-gallery model. That code calls
# the functions named <package>_<operation> below (decad_extrude, sketch_new_radius, r3_new_vec) and the methods of
# the classes below, one for each entry of the API table in port/go2py/api.go. Everything Fusion needs that the
# gallery does not say lives here, once, for every gear: where a sketch's origin goes, how a dimension binds to a
# user parameter, how an axial edge is found on a body. docs/fusion/playbook.md and docs/fusion/spurgear.md hold the
# Fusion findings behind each rule, quoted here by anchor.
#
# The translated code is the gallery's: it creates sketches, features and bodies in the gallery's order, and passes
# the role name of each one it creates. This module never decides geometry.

import functools
import math
import os
import tempfile
import time
from contextlib import contextmanager
from typing import cast
import adsk.core
import adsk.fusion
from ...lib import fusion360utils as futil
from . import solids

DECAD_ALONG = 1
DECAD_AGAINST = -1

# Two coordinates closer than this, in cm, are one value to Fusion's sketch solver.
SAME_COORDINATE = 1e-6

# The active runtime. A translated function reaches the design through the objects it is handed, except
# sketch_new_world(), which the gallery calls with no argument.
_active = None


# Fusion's Text Commands window does not repaint while the add-in blocks the main thread, so a step that never
# returns leaves no trace there. The progress file is written and flushed line by line, so it shows the step a hung
# build stopped in.
PROGRESS_FILE = os.path.join(tempfile.gettempdir(), 'geargen-progress.log')


def progress(message):
    try:
        with open(PROGRESS_FILE, 'a') as out:
            out.write(f'{time.strftime("%H:%M:%S")} {message}\n')
            out.flush()
            os.fsync(out.fileno())
    except OSError:
        pass


@contextmanager
def timed(what):
    """Log how long a step takes, so a slow build shows which operation is slow."""
    progress(f'start {what}')
    start = time.perf_counter()
    try:
        yield
    finally:
        message = f'{what}: {time.perf_counter() - start:.2f}s'
        progress(message)
        futil.log(message)


def logged(function):
    """Time a decad operation under its role name."""
    @functools.wraps(function)
    def wrapper(*args, **kwargs):
        with timed(kwargs.get('name') or function.__name__):
            return function(*args, **kwargs)
    return wrapper


class SketchOnly(Exception):
    """Raised by the first extrude when the dialog asks for sketches only, which ends the build."""


class Vec:
    def __init__(self, x, y, z):
        self.x, self.y, self.z = x, y, z

    def add(self, other):
        return Vec(self.x + other.x, self.y + other.y, self.z + other.z)

    def sub(self, other):
        return Vec(self.x - other.x, self.y - other.y, self.z - other.z)

    def scale(self, k):
        return Vec(self.x * k, self.y * k, self.z * k)

    def len(self):
        return math.sqrt(self.x * self.x + self.y * self.y + self.z * self.z)

    def dot(self, other):
        return self.x * other.x + self.y * other.y + self.z * other.z

    def cross(self, other):
        return Vec(self.y * other.z - self.z * other.y, self.z * other.x - self.x * other.z,
                   self.x * other.y - self.y * other.x)

    def unit(self):
        n = self.len()
        return Vec(self.x / n, self.y / n, self.z / n)

    # The gallery's r3.Vec names its fields in capitals.
    X = property(lambda self: self.x)
    Y = property(lambda self: self.y)
    Z = property(lambda self: self.z)


def r3_new_vec(x, y, z):
    return Vec(x, y, z)


def vec_of(point):
    return Vec(point.x, point.y, point.z)


class Frame:
    """An origin and three axes in world cm. n is the gear axis and the normal of the sketch plane."""

    def __init__(self, origin, u, v, n):
        self._origin, self._u, self._v, self._n = origin, u, v, n

    def origin(self):
        return self._origin

    def u(self):
        return self._u

    def v(self):
        return self._v

    def n(self):
        return self._n


def r3_new_frame(origin, u, v):
    return Frame(origin, u, v, u.cross(v).unit())


class Value:
    """A user parameter. base() is its value in the unit of the translated code; expression names it for a
    dimension or a feature. [PB-UNITS]"""

    def __init__(self, name, parameter, scale=1.0):
        self.expression = name
        self._parameter = parameter
        self._scale = scale

    def base(self):
        return self._parameter.value / self._scale


class Distance:
    def __init__(self, D, Dir):
        self.D, self.Dir = D, Dir


def decad_distance(D, Dir):
    return Distance(D, Dir)


class DistanceSide:
    def __init__(self, D):
        self.D = D


def decad_distance_side(D):
    return DistanceSide(D)


class TwoSided:
    """An extent that reaches One from the sketch along its normal and Two against it."""

    def __init__(self, One, Two):
        self.One, self.Two = One, Two


def decad_two_sided(One, Two):
    return TwoSided(One, Two)


def units_millimeters(x):
    # The translated code already runs in a unit the runtime converts, so a length is its number.
    return x


class CircularPattern:
    def __init__(self, Center, Axis, Count):
        self.Center, self.Axis, self.Count = Center, Axis, Count


def decad_circular_pattern(Center, Axis, Count):
    return CircularPattern(Center, Axis, Count)


def value_input(value, scale=1.0):
    """A ValueInput for a Value (its user parameter, so the feature stays parametric) or a number, which is in
    the unit of the translated code and becomes centimetres by scale. [PB-UNITS]"""
    if isinstance(value, Value):
        return adsk.core.ValueInput.createByString(value.expression)
    return adsk.core.ValueInput.createByReal(value * scale)


class Runtime:
    """The design a translated gallery model builds in. It is the gallery's Document and World."""

    def __init__(self, component, plane, anchor, parameters, sketch_only=False, scale=1.0):
        # scale is the centimetres of one unit of length in the translated code. The spur-family gears run in
        # centimetres (1.0). A gallery model with absolute lengths in millimetres runs in millimetres (0.1), and
        # the runtime converts at every place a length enters or leaves Fusion. [PB-UNITS]
        self.scale = scale
        # component: the adsk.fusion.Component to build in.
        # plane: the ConstructionPlane the lower cap lies on.
        # anchor: a SketchPoint at the gear centre, projected into a fully constrained sketch.
        # parameters: a function from a gallery table name to (Fusion parameter name, adsk Parameter).
        self.component = component
        self.plane = plane
        self.anchor = anchor
        self._parameters = parameters
        self.sketch_only = sketch_only
        self.sketches = []
        self.helpers = []
        self._names = {}
        # The gallery builds a gear about the local origin and +Z. frame is that local frame, and
        # placement is where it lies in the design: the anchor, the sketch's axes and their normal.
        self.frame: Frame = Frame(Vec(0, 0, 0), Vec(1, 0, 0), Vec(0, 1, 0), Vec(0, 0, 1))
        self.placement: Frame = self.frame

    def activate(self):
        global _active
        _active = self
        return self

    def build_frame(self, sketch):
        """Place the gear: its origin is the anchor and its axes are the sketch's. [SPUR-F-LOCAL-ORIGIN]

        Returns the local frame the translated code builds in. Positions that come out of the design
        (vertices of edges) are in that frame, and positions that go in (the pattern axis, a plane's
        frame, an edge's end point) are mapped to the design, as the gallery's Place does at the end.
        """
        u = vec_of(sketch.xDirection)
        v = vec_of(sketch.yDirection)
        self.placement = Frame(vec_of(self.anchor.worldGeometry), u, v, u.cross(v).unit())
        return self.frame

    def to_world(self, point):
        p = self.placement
        local = point.scale(self.scale)
        return p.origin().add(p.u().scale(local.x)).add(p.v().scale(local.y)).add(p.n().scale(local.z))

    def to_world_dir(self, direction):
        p = self.placement
        return p.u().scale(direction.x).add(p.v().scale(direction.y)).add(p.n().scale(direction.z))

    def to_local(self, point):
        p = self.placement
        d = point.sub(p.origin()).scale(1.0 / self.scale)
        return Vec(d.dot(p.u()), d.dot(p.v()), d.dot(p.n()))

    # decad.Document
    def param(self, name):
        parameterName, parameter = self._parameters(name)
        return Value(parameterName, parameter, self.scale)

    # sketch.World
    def params(self):
        return None

    def xy(self):
        return Plane(self, self.plane)

    def unique(self, name):
        """A role name that repeats gets an index: Tooth Profile, Tooth Profile 2."""
        count = self._names.get(name, 0) + 1
        self._names[name] = count
        return name if count == 1 else f'{name} {count}'

    def derive(self, p):
        """The gear dimensions, read from the user parameters the gallery table defines."""
        class Dimensions:
            pass
        d = Dimensions()
        d.pitch, d.base = self.param('pitch_radius').base(), self.param('base_radius').base()
        d.root, d.tip = self.param('root_radius').base(), self.param('tip_radius').base()
        d.fillet = self.param('fillet_radius').base()
        return d

    def create_sketch(self, plane, name):
        name = self.unique(name)
        fsketch: adsk.fusion.Sketch = self.component.sketches.add(plane.entity)
        solids.name_feature(fsketch, name)
        fsketch.isVisible = True
        sketch = Sketch(self, fsketch)
        self.sketches.append(fsketch)
        return sketch

    def create_plane_from_frame(self, frame, name):
        offset = frame.origin().sub(self.frame.origin()).dot(self.frame.n()) * self.scale
        name = self.unique(name)
        planes: adsk.fusion.ConstructionPlanes = self.component.constructionPlanes
        planeInput: adsk.fusion.ConstructionPlaneInput = planes.createInput()
        planeInput.setByOffset(self.plane, adsk.core.ValueInput.createByReal(offset))
        entity = planes.add(planeInput)
        solids.name_feature(entity, name)
        entity.isLightBulbOn = True
        self.helpers.append(entity)
        return Plane(self, entity)

    def hide_helpers(self):
        for entity in self.helpers:
            entity.isLightBulbOn = False
        for fsketch in self.sketches:
            fsketch.isVisible = False


def sketch_new_world():
    return _active


def derive(p):
    return _active.derive(p)


class Plane:
    def __init__(self, runtime, entity):
        self.runtime, self.entity = runtime, entity


class Circle:
    """A circle the gallery drew: the Fusion circle and the point the gallery placed its centre by."""

    def __init__(self, circle, center):
        self.circle = circle
        self.Center = center


class Spline:
    """A fitted spline the gallery asked for. Fusion creates it when the sketch is drawn."""

    def __init__(self, points):
        self.points = points
        self.fusion = None


class Constraint:
    """A dimension that a sketch will create: a radius or a diameter of a circle."""

    def __init__(self, kind, circle, value):
        self.kind, self.value = kind, value
        self.circle = circle.circle if isinstance(circle, Circle) else circle
        self.dimension = None


def sketch_new_radius(circle, value):
    return Constraint('radius', circle, value)


def sketch_new_diameter(circle, value):
    return Constraint('diameter', circle, value)


class PendingPoint:
    """A point the gallery places by coordinates. Fusion creates it with the first curve that uses it."""

    def __init__(self, x, y, arcEnd):
        self.x = x
        self.y = y
        # An arc end is placed by one coordinate; its radius comes from the arc or circle it ends.
        self.arcEnd = arcEnd
        # The SketchPoint, once a curve has created it.
        self.point = None


class Profile:
    Valid = True

    def __init__(self, fprofile):
        self.fprofile = fprofile
        self.Outer = []
        self.Holes = []
        for loop in fprofile.profileLoops:
            if loop.isOuter:
                self.Outer = [curve for curve in loop.profileCurves]
            else:
                self.Holes.append([curve for curve in loop.profileCurves])


class Sketch:
    """A Fusion sketch the translated gallery code draws in.

    The gallery calls dimension_point, dimension_arc_end, create_line, create_arc, create_fit_spline and
    create_circle in its own order. This class records them and draws them in solve(), in the order Fusion
    needs: splines first, so every line and arc ends on a spline's own fit points, then lines, arcs, the
    dimensions from the local origin, and last the coincident constraint that moves the local origin onto the
    anchor. [SPUR-F-GALLERY-SKETCH] [SPUR-F-ARC-CENTRE] [SPUR-F-ALIGN-DUPLICATE] [SPUR-F-LOCAL-ORIGIN]
    """

    def __init__(self, runtime, fsketch, origin=None, rootCircle=None, rootRadius=None):
        self.runtime = runtime
        self._scale = runtime.scale if runtime is not None else 1.0
        self.sketch: adsk.fusion.Sketch = fsketch
        # The local origin is a point the anchor constraint can move, which the sketch's own origin is not.
        self._origin = origin if origin is not None else fsketch.sketchPoints.add(adsk.core.Point3D.create(0, 0, 0))
        # A caller that draws the root circle itself passes it, and the root arc then lies on that circle.
        self._rootCircle = rootCircle
        self._rootRadius = rootRadius
        self._points = []
        self._lines = []
        self._arcs = []
        self._splines = []
        self._patterns = []
        self._constraints = []
        self._bindings = []
        self._dimensioned = []

    # sketch.Sketch
    def origin(self):
        return self._origin

    def dimension_point(self, x, y):
        point = PendingPoint(x, y, False)
        self._points.append(point)
        return point

    def dimension_arc_end(self, x, y):
        point = PendingPoint(x, y, True)
        self._points.append(point)
        return point

    def create_line(self, start, end):
        self._lines.append((start, end))

    def create_arc(self, center, start, end):
        self._arcs.append((center, start, end))

    def create_fit_spline(self, *points):
        spline = Spline(points)
        self._splines.append(spline)
        return spline

    def create_point(self, x, y):
        """A point the gallery places without dimensioning it: the pattern places it."""
        return PendingPoint(x, y, False)

    def create_pattern_circular_ring(self, splines, center, n, start, end):
        """A circular pattern of splines about center, n copies in all, closing into a ring. [PB-SPLINE-RING]"""
        self._patterns.append((splines, center, n, start, end))
        return splines[0]

    def create_circle(self, center, radius):
        circles: adsk.fusion.SketchCircles = self.sketch.sketchCurves.sketchCircles
        if isinstance(center, PendingPoint):
            # A circle whose centre the gallery dimensions from the origin: Fusion makes the centre point with
            # the circle, and the dimension step then places it.
            circle = circles.addByCenterRadius(
                adsk.core.Point3D.create(center.x * self._scale, center.y * self._scale, 0), radius * self._scale)
            center.point = circle.centerSketchPoint
            return Circle(circle, center)
        return Circle(circles.addByCenterRadius(center, radius * self._scale), center)

    def add_constraint(self, constraint):
        self._constraints.append(constraint)

    def bind(self, constraint, table, name):
        self._bindings.append((constraint, name))

    def solve(self):
        with timed(f'{self.sketch.name} solve'):
            self.finish()
            with timed(f'{self.sketch.name} anchor'):
                self._anchor()

    def profiles(self):
        return [Profile(profile) for profile in self.sketch.profiles]

    # The drawing
    def finish(self):
        """Draw everything recorded, without moving the local origin."""
        with timed(f'{self.sketch.name} draw'):
            self._drawSplines()
            self._drawLines()
            self._drawArcs()
        with timed(f'{self.sketch.name} dimension {len(self._points)} points'):
            for point in self._points:
                self._dimensionPoint(point)
            self._points = []
            for constraint in self._constraints:
                self._dimensionCircle(constraint)
            self._constraints = []
        for pattern in self._patterns:
            with timed(f'{self.sketch.name} pattern'):
                self._pattern(*pattern)
        self._patterns = []
        for constraint, name in self._bindings:
            self._bind(constraint, name)
        self._bindings = []

    def _anchor(self):
        """Move the local origin onto the anchor, last, once every dimension is in place. [SPUR-F-LOCAL-ORIGIN]"""
        projected = adsk.fusion.SketchPoint.cast(self.sketch.project(self.runtime.anchor).item(0))
        if projected is None:
            raise RuntimeError(f'{self.sketch.name}: anchor projection produced no SketchPoint')
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        constraints.addCoincident(self._origin, projected)

    def _drawSplines(self):
        splines: adsk.fusion.SketchFittedSplines = self.sketch.sketchCurves.sketchFittedSplines
        for spline in self._splines:
            collection = adsk.core.ObjectCollection.create()
            for point in spline.points:
                collection.add(adsk.core.Point3D.create(point.x * self._scale, point.y * self._scale, 0))
            spline.fusion = splines.add(collection)
            fits: adsk.fusion.SketchPointList = spline.fusion.fitPoints
            for i, point in enumerate(spline.points):
                point.point = fits.item(i)
        self._splines = []

    def _pattern(self, splines, center, n, start, end):
        """Copy the seed splines n - 1 times about center, then tie the seed's free end to the first copy's start.
        Fusion's copies carry their own points and the closed outline needs only that one coincident: every
        neighbouring pair would add redundant constraints. [PB-SPLINE-RING]"""
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        centre = center.point if isinstance(center, PendingPoint) else center
        patternInput = constraints.createCircularPatternInput([spline.fusion for spline in splines], centre)
        patternInput.quantity = adsk.core.ValueInput.createByReal(n)
        patternInput.totalAngle = adsk.core.ValueInput.createByString('360 deg')
        pattern = constraints.addCircularPattern(patternInput)
        if pattern is None:
            raise RuntimeError(f'{self.sketch.name}: the circular pattern was not created')
        # The first copy starts where the seed's start turned one step about the centre.
        origin, first = centre.geometry, start.point.geometry
        step = 2 * math.pi / n
        dx, dy = first.x - origin.x, first.y - origin.y
        target = (origin.x + dx * math.cos(step) - dy * math.sin(step), origin.y + dx * math.sin(step) + dy * math.cos(step))
        nearest, gap = None, None
        for entity in pattern.createdEntities:
            fitted = adsk.fusion.SketchFittedSpline.cast(entity)
            if fitted is None:
                continue
            point = fitted.fitPoints.item(0)
            distance = math.hypot(point.geometry.x - target[0], point.geometry.y - target[1])
            if gap is None or distance < gap:
                nearest, gap = point, distance
        if nearest is None or gap > SAME_COORDINATE * 100:
            raise RuntimeError(f'{self.sketch.name}: no copy of the pattern starts where the seed ends')
        constraints.addCoincident(end.point, nearest)

    def _end(self, point):
        if point.point is not None:
            return point.point
        return adsk.core.Point3D.create(point.x * self._scale, point.y * self._scale, 0)

    def _drawLines(self):
        lines: adsk.fusion.SketchLines = self.sketch.sketchCurves.sketchLines
        for start, end in self._lines:
            line: adsk.fusion.SketchLine = lines.addByTwoPoints(self._end(start), self._end(end))
            if start.point is None:
                start.point = line.startSketchPoint
            if end.point is None:
                end.point = line.endSketchPoint
        self._lines = []

    def _onRootCircle(self, point):
        assert self._rootRadius is not None
        return abs(math.hypot(point.x, point.y) - self._rootRadius) < SAME_COORDINATE

    def _drawArcs(self):
        arcs: adsk.fusion.SketchArcs = self.sketch.sketchCurves.sketchArcs
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        for center, start, end in self._arcs:
            if self._rootCircle is not None and self._onRootCircle(start) and self._onRootCircle(end):
                # The root arc is part of the root circle the caller already drew, which the parameters size.
                # Its ends sit on that circle instead of getting a second arc. [SPUR-F-ROOT-ARC]
                for point in (start, end):
                    point.arcEnd = True
                    constraints.addCoincident(point.point, self._rootCircle)
                continue
            arc: adsk.fusion.SketchArc = arcs.addByCenterStartEnd(center, start.point, end.point)
            # Fusion makes its own centre point for the arc; tie it to the local origin. [SPUR-F-ARC-CENTRE]
            constraints.addCoincident(arc.centerSketchPoint, center)
        self._arcs = []

    def _dimensionPoint(self, point):
        horizontal = adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation
        vertical = adsk.fusion.DimensionOrientations.VerticalDimensionOrientation
        if not point.arcEnd:
            self._dimension(point, horizontal)
            self._dimension(point, vertical)
        elif abs(point.x) >= abs(point.y):
            self._dimension(point, vertical)
        else:
            self._dimension(point, horizontal)
        self._dimensioned.append(point)

    def _dimension(self, point, orientation):
        dims: adsk.fusion.SketchDimensions = self.sketch.sketchDimensions
        textPoint = adsk.core.Point3D.create(point.x * self._scale, point.y * self._scale, 0)
        try:
            dims.addDistanceDimension(self._origin, point.point, orientation, textPoint)
            return
        except RuntimeError:
            partner = self._sameCoordinate(point, orientation)
            if partner is None:
                raise
        # Fusion refuses a second dimension with the value and direction of an earlier one from the
        # same origin, as at tooth angle 0 where both flanks start at one x. Aligning the two points
        # fixes the same coordinate. [SPUR-F-ALIGN-DUPLICATE]
        constraints: adsk.fusion.GeometricConstraints = self.sketch.geometricConstraints
        if orientation == adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation:
            constraints.addVerticalPoints(point.point, partner.point)
        else:
            constraints.addHorizontalPoints(point.point, partner.point)

    def _sameCoordinate(self, point, orientation):
        horizontal = orientation == adsk.fusion.DimensionOrientations.HorizontalDimensionOrientation
        for other in self._dimensioned:
            if abs((other.x - point.x) if horizontal else (other.y - point.y)) < SAME_COORDINATE:
                return other
        return None

    def _dimensionCircle(self, constraint):
        dims: adsk.fusion.SketchDimensions = self.sketch.sketchDimensions
        radius = constraint.circle.radius
        textPoint = adsk.core.Point3D.create(radius, radius, 0)
        if constraint.kind == 'radius':
            constraint.dimension = dims.addRadialDimension(constraint.circle, textPoint)
        else:
            constraint.dimension = dims.addDiameterDimension(constraint.circle, textPoint)

    def _bind(self, constraint, name):
        """Drive the dimension from the user parameter the gallery bound it to."""
        parameterName, _ = self.runtime._parameters(name)
        constraint.dimension.parameter.expression = parameterName


def unconstrained_entities(fsketch, limit=24):
    """Describe the curves and fit points a sketch leaves free, in mm, so a failed check says what to constrain."""
    found = []
    curves = fsketch.sketchCurves
    for i in range(curves.count):
        curve = curves.item(i)
        if curve.isFullyConstrained:
            continue
        kind = curve.objectType.split('::')[-1]
        start = curve.startSketchPoint.geometry if hasattr(curve, 'startSketchPoint') else None
        where = '' if start is None else f' from ({start.x * 10:.3f}, {start.y * 10:.3f})'
        loose = []
        fitted = adsk.fusion.SketchFittedSpline.cast(curve)
        if fitted is not None:
            for j in range(fitted.fitPoints.count):
                point = fitted.fitPoints.item(j)
                if not point.isFullyConstrained:
                    loose.append(f'{j}:({point.geometry.x * 10:.3f}, {point.geometry.y * 10:.3f})')
        found.append(f'{kind}{where}' + (f' free fit points {", ".join(loose)}' if loose else ''))
    points = fsketch.sketchPoints
    for i in range(points.count):
        point = points.item(i)
        if not point.isFullyConstrained:
            found.append(f'point ({point.geometry.x * 10:.3f}, {point.geometry.y * 10:.3f})')
    more = len(found) - limit
    return found[:limit] + ([f'and {more} more'] if more > 0 else [])


def sketchcheck_verify_fully_constrained(sketch):
    with timed(f'{sketch.sketch.name} constraint check'):
        constrained = sketch.sketch.isFullyConstrained
    if not constrained:
        free = unconstrained_entities(sketch.sketch)
        raise RuntimeError(f'{sketch.sketch.name}: sketch is not fully constrained; free: ' + '; '.join(free))


