# Bodies, features and edge selection


class Body:
    def __init__(self, runtime, body):
        self.runtime = runtime
        self.body: adsk.fusion.BRepBody = body

    def is_solid(self):
        return self.body.isSolid

    def centroid(self):
        return Centroid(self.runtime, self.body.physicalProperties.centerOfMass)

    def faces(self):
        return [Face(self.runtime, f) for f in self.body.faces]


class Position:
    def __init__(self, runtime, point):
        self.Value = runtime.to_local(vec_of(point))


class Centroid:
    def __init__(self, runtime, point):
        self.Value = runtime.to_local(vec_of(point))


class Vertex:
    def __init__(self, runtime, point):
        self._runtime = runtime
        self._point = point

    def position(self):
        return Position(self._runtime, self._point)


class Edge:
    def __init__(self, runtime, edge):
        self.runtime = runtime
        self.edge: adsk.fusion.BRepEdge = edge
        self._ends = None
        self._axial = None

    def ends(self):
        if self._ends is None:
            self._ends = (self.edge.startVertex.geometry, self.edge.endVertex.geometry)
        return self._ends

    def is_axial(self):
        if self._axial is None:
            axis = self.runtime.placement.n()
            a, b = (vec_of(p) for p in self.ends())
            d = b.sub(a)
            length = d.len()
            self._axial = length > 0 and abs(abs(d.dot(axis)) - length) <= 1e-6 * max(length, 1.0)
        return self._axial

    def end(self):
        """The end of an axial edge on the upper cap, the other end from start()."""
        a, b = self.ends()
        s = self.start()
        return Vertex(self.runtime, b) if s._point is a else Vertex(self.runtime, a)

    def curve(self):
        if self.edge.geometry.curveType == adsk.core.Curve3DTypes.Line3DCurveType:
            return Line3()
        return Curve()

    def __hash__(self):
        return hash(self.edge.tempId)

    def __eq__(self, other):
        return isinstance(other, Edge) and self.edge.tempId == other.edge.tempId

    def axisDirection(self):
        a, b = (vec_of(p) for p in self.ends())
        return b.sub(a).unit()

    def start(self):
        """The end of an axial edge on the lower cap; an edge that is not axial keeps Fusion's start."""
        a, b = self.ends()
        axis = self.runtime.placement.n()
        if self.is_axial() and vec_of(b).dot(axis) < vec_of(a).dot(axis):
            return Vertex(self.runtime, b)
        return Vertex(self.runtime, a)


class Curve:
    """A curve of an edge that is not a straight line."""


class Line3(Curve):
    """A straight edge."""


def decad_is_line3(curve):
    return isinstance(curve, Line3)


class Length:
    def __init__(self, value):
        self._value = value

    def base(self):
        return self._value


class Surface:
    """A surface of a face that is not a cylinder."""


class Cylinder(Surface):
    def __init__(self, radius):
        self.Radius = Length(radius)


def decad_is_cylinder(surface):
    return isinstance(surface, Cylinder)


class Face:
    def __init__(self, runtime, face):
        self.runtime = runtime
        self.face: adsk.fusion.BRepFace = face

    def surface(self):
        if self.face.geometry.surfaceType == adsk.core.SurfaceTypes.CylinderSurfaceType:
            return Cylinder(cast(adsk.core.Cylinder, self.face.geometry).radius / self.runtime.scale)
        return Surface()

    def edges(self):
        return [Edge(self.runtime, e) for e in self.face.edges]


class Predicate:
    """A condition on the edges of a body. matches() receives the Edge and the body it came from."""

    def __init__(self, test):
        self.test = test

    def matches(self, edge, body):
        return self.test(edge, body)


def decad_parallel_to(axis):
    def test(edge, body):
        a, b = (vec_of(p) for p in edge.ends())
        if not isinstance(edge.curve(), Line3) or b.sub(a).len() == 0:
            return False
        world = edge.runtime.to_world_dir(axis).unit()
        return abs(abs(edge.axisDirection().dot(world)) - 1) < 1e-6
    return Predicate(test)


def decad_endpoint_at(point):
    def test(edge, body):
        world = edge.runtime.to_world(point)
        return any(vec_of(p).sub(world).len() <= SAME_COORDINATE for p in edge.ends())
    return Predicate(test)


def decad_circular():
    def test(edge, body):
        return edge.edge.geometry.curveType in (
            adsk.core.Curve3DTypes.Circle3DCurveType, adsk.core.Curve3DTypes.Arc3DCurveType)
    return Predicate(test)


def decad_longer_than(length):
    def test(edge, body):
        return edge.edge.length / edge.runtime.scale > length
    return Predicate(test)


def decad_concave():
    # The concave edges are asked of Fusion once per selection, not once per edge.
    memo = {}

    def test(edge, body):
        if 'tokens' not in memo:
            memo['tokens'] = {e.tempId for e in body.body.concaveEdges}
        return edge.edge.tempId in memo['tokens']
    return Predicate(test)


class FaceSelector:
    """Planar end caps of a body: the faces perpendicular to the gear axis at its lowest or highest position."""

    def __init__(self, high):
        self.high = high
        self.body = None


def decad_cap_start(body):
    selector = FaceSelector(False)
    selector.body = body
    return selector


def decad_cap_end(body):
    selector = FaceSelector(True)
    selector.body = body
    return selector


def cap_faces(runtime, body, high):
    axis = runtime.placement.n()
    planar = []
    for face in body.body.faces:
        if face.geometry.surfaceType != adsk.core.SurfaceTypes.PlaneSurfaceType:
            continue
        plane = cast(adsk.core.Plane, face.geometry)
        normal = vec_of(plane.normal)
        if abs(abs(normal.dot(axis)) - 1.0) > 1e-6:
            continue
        planar.append((vec_of(plane.origin).dot(axis), face))
    if not planar:
        return []
    extreme = max(h for h, _ in planar) if high else min(h for h, _ in planar)
    return [face for h, face in planar if abs(h - extreme) <= 1e-5]


def decad_outer_loop_of(selector):
    # The cap's outer loop is read once per selection, not once per edge.
    memo = {}

    def test(edge, body):
        if 'tokens' not in memo:
            tokens = set()
            for face in cap_faces(edge.runtime, selector.body, selector.high):
                for loop in face.loops:
                    if loop.isOuter:
                        tokens.update(e.tempId for e in loop.edges)
            memo['tokens'] = tokens
        return edge.edge.tempId in memo['tokens']
    return Predicate(test)


class Selector:
    def __init__(self, groups, count=None):
        self.groups = groups
        self.count = count

    def or_(self, *predicates):
        """Add a group of conditions, in place, as the gallery's EdgeQuery does."""
        self.groups.append(list(predicates))
        return self

    def exactly(self, count):
        self.count = count
        return self

    def select_edges(self, body):
        edges = []
        for fedge in body.body.edges:
            edge = Edge(body.runtime, fedge)
            if any(all(p.matches(edge, body) for p in group) for group in self.groups):
                edges.append(edge)
        return edges


def decad_edges(*predicates):
    return Selector([list(predicates)])


def _edge_collection(selector, body, what):
    edges = selector.select_edges(body)
    if selector.count is not None and len(edges) != selector.count:
        raise RuntimeError(f'{what}: selected {len(edges)} edges, want {selector.count}')
    collection = adsk.core.ObjectCollection.create()
    for edge in edges:
        collection.add(edge.edge)
    if collection.count == 0:
        raise RuntimeError(f'{what}: no edges selected')
    return collection


@logged
def decad_extrude(doc, sketch, profile, extent, name, body):
    if doc.sketch_only:
        raise SketchOnly()
    extrudes: adsk.fusion.ExtrudeFeatures = doc.component.features.extrudeFeatures
    operation = adsk.fusion.FeatureOperations.NewBodyFeatureOperation
    extrudeInput: adsk.fusion.ExtrudeFeatureInput = extrudes.createInput(profile.fprofile, operation)
    if isinstance(extent, TwoSided):
        extrudeInput.setTwoSidesExtent(
            adsk.fusion.DistanceExtentDefinition.create(value_input(extent.One.D, doc.scale)),
            adsk.fusion.DistanceExtentDefinition.create(value_input(extent.Two.D, doc.scale)))
    else:
        distance = adsk.fusion.DistanceExtentDefinition.create(value_input(extent.D, doc.scale))
        direction = (adsk.fusion.ExtentDirections.PositiveExtentDirection if extent.Dir == DECAD_ALONG
                     else adsk.fusion.ExtentDirections.NegativeExtentDirection)
        extrudeInput.setOneSideExtent(distance, direction)
    extrude: adsk.fusion.ExtrudeFeature = extrudes.add(extrudeInput)
    solids.name_feature(extrude, name)
    if extrude.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {extrude.bodies.count}')
    fbody: adsk.fusion.BRepBody = extrude.bodies.item(0)
    solids.name_feature(fbody, body)
    return Body(doc, fbody)


def _axis_through(runtime, pattern, name):
    """A construction axis along the pattern axis: the axis of a cylindrical face of the component's bodies."""
    center, axis = runtime.to_world(pattern.Center), runtime.to_world_dir(pattern.Axis).unit()
    for fbody in runtime.component.bRepBodies:
        for face in fbody.faces:
            if face.geometry.surfaceType != adsk.core.SurfaceTypes.CylinderSurfaceType:
                continue
            cylinder = cast(adsk.core.Cylinder, face.geometry)
            direction = vec_of(cylinder.axis)
            if abs(abs(direction.dot(axis)) - 1.0) > 1e-6:
                continue
            offset = center.sub(vec_of(cylinder.origin))
            if offset.sub(direction.scale(offset.dot(direction))).len() > 1e-5:
                continue
            axes: adsk.fusion.ConstructionAxes = runtime.component.constructionAxes
            axisInput: adsk.fusion.ConstructionAxisInput = axes.createInput()
            axisInput.setByCircularFace(face)
            entity = axes.add(axisInput)
            solids.name_feature(entity, name)
            entity.isLightBulbOn = False
            return entity
    raise RuntimeError(f'{name}: no cylindrical face on the pattern axis')


@logged
def decad_pattern_copies(tooth, pattern, name):
    runtime = tooth.runtime
    axis = _axis_through(runtime, pattern, name + ' Axis')
    entities = adsk.core.ObjectCollection.create()
    entities.add(tooth.body)
    patterns: adsk.fusion.CircularPatternFeatures = runtime.component.features.circularPatternFeatures
    patternInput: adsk.fusion.CircularPatternFeatureInput = patterns.createInput(entities, axis)
    patternInput.quantity = adsk.core.ValueInput.createByReal(pattern.Count)
    patternInput.totalAngle = adsk.core.ValueInput.createByString('360 deg')
    patternInput.isSymmetric = False
    feature: adsk.fusion.CircularPatternFeature = patterns.add(patternInput)
    solids.name_feature(feature, name)
    # The result may or may not list the original body; the copies are the others.
    copies = [Body(runtime, b) for b in feature.bodies if b.entityToken != tooth.body.entityToken]
    if not copies:
        raise RuntimeError(f'{name}: the pattern made no copies')
    return copies


def _combine(base, tools, operation, name):
    collection = adsk.core.ObjectCollection.create()
    for tool in tools:
        collection.add(tool.body)
    combines: adsk.fusion.CombineFeatures = base.runtime.component.features.combineFeatures
    combineInput: adsk.fusion.CombineFeatureInput = combines.createInput(base.body, collection)
    combineInput.operation = operation
    feature = combines.add(combineInput)
    solids.name_feature(feature, name)
    return base


@logged
def decad_union(base, *others, name):
    return _combine(base, others, adsk.fusion.FeatureOperations.JoinFeatureOperation, name)


@logged
def decad_cut(base, tool, name):
    return _combine(base, [tool], adsk.fusion.FeatureOperations.CutFeatureOperation, name)


@logged
def decad_fillet(body, selector, radius, name):
    with timed(f'{name} edge selection'):
        edges = _edge_collection(selector, body, name)
    fillets: adsk.fusion.FilletFeatures = body.runtime.component.features.filletFeatures
    filletInput: adsk.fusion.FilletFeatureInput = fillets.createInput()
    filletInput.addConstantRadiusEdgeSet(edges, value_input(radius, body.runtime.scale), False)
    with timed(f'{name} feature'):
        feature = fillets.add(filletInput)
    solids.name_feature(feature, name)
    return body


@logged
def decad_chamfer(body, selector, setback, name):
    with timed(f'{name} edge selection'):
        edges = _edge_collection(selector, body, name)
    chamfers: adsk.fusion.ChamferFeatures = body.runtime.component.features.chamferFeatures
    chamferInput: adsk.fusion.ChamferFeatureInput = chamfers.createInput2()
    chamferInput.chamferEdgeSets.addEqualDistanceChamferEdgeSet(edges, value_input(setback, body.runtime.scale), False)
    with timed(f'{name} feature'):
        feature = chamfers.add(chamferInput)
    solids.name_feature(feature, name)
    return body


@logged
def decad_loft(doc, lowerSketch, lowerProfile, upperSketch, upperProfile, name, body):
    if doc.sketch_only:
        raise SketchOnly()
    lofts: adsk.fusion.LoftFeatures = doc.component.features.loftFeatures
    loftInput: adsk.fusion.LoftFeatureInput = lofts.createInput(adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    loftInput.loftSections.add(lowerProfile.fprofile)
    loftInput.loftSections.add(upperProfile.fprofile)
    loft: adsk.fusion.LoftFeature = lofts.add(loftInput)
    solids.name_feature(loft, name)
    if loft.bodies.count != 1:
        raise RuntimeError(f'{name}: expected one body, got {loft.bodies.count}')
    fbody: adsk.fusion.BRepBody = loft.bodies.item(0)
    solids.name_feature(fbody, body)
    return Body(doc, fbody)


class MirrorFrame:
    def __init__(self, Frame):
        self.Frame = Frame


def decad_mirror_frame(Frame):
    return MirrorFrame(Frame)


@logged
def decad_mirrored_copy(source, mirror, name, body):
    runtime = source.runtime
    plane = runtime.create_plane_from_frame(mirror.Frame, name + ' Plane')
    entities = adsk.core.ObjectCollection.create()
    entities.add(source.body)
    mirrors: adsk.fusion.MirrorFeatures = runtime.component.features.mirrorFeatures
    mirrorInput: adsk.fusion.MirrorFeatureInput = mirrors.createInput(entities, plane.entity)
    mirrorInput.isCombine = False
    feature: adsk.fusion.MirrorFeature = mirrors.add(mirrorInput)
    solids.name_feature(feature, name)
    copies = [b for b in feature.bodies if b.entityToken != source.body.entityToken]
    if len(copies) != 1:
        raise RuntimeError(f'{name}: expected one mirrored body, got {len(copies)}')
    solids.name_feature(copies[0], body)
    return Body(runtime, copies[0])
